mapper.select:
select gls.id, gls.mix_area, gls.glue, gls.machine_code, ma.machine_name, gls.loss_rate, gls.create_by, gls.create_time, gls.update_by, gls.update_time, gls.del_flag, gls.remark from t_glue_loss_setting gls left join T_MIX_MACHINE ma on gls.mix_area=ma.mix_area and gls.machine_code=ma.machine_code and ma.del_flag='0'
gls.del_flag = '0' and gls.mix_area = #{mixArea} and instr(gls.glue , #{glue})>0 and gls.machine_code = #{machineCode}
order by gls.create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType= VARCHAR} mix_area,#{data.glue,jdbcType= VARCHAR} glue,#{data.machineCode,jdbcType= VARCHAR} machine_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_loss_setting m inner join temp_table t on m.mix_area=t.mix_area and ifnull(m.glue,'GLUE_EMPTY') = ifnull(t.glue,'GLUE_EMPTY') and ifnull(m.machine_code,'MACHINE_EMPTY')=ifnull(t.machine_code,'MACHINE_EMPTY') and m.del_flag ='0'

mapper.insert:
insert into t_glue_loss_setting (id,mix_area,glue,machine_code,loss_rate,create_by,create_time,update_by,update_time,del_flag,remark ) select NULL id, x.* from (
select #{glueLossSetting.mixArea,jdbcType= VARCHAR} mix_area, #{glueLossSetting.glue,jdbcType= VARCHAR} glue, #{glueLossSetting.machineCode,jdbcType= VARCHAR} machine_code, #{glueLossSetting.lossRate,jdbcType=DOUBLE} loss_rate, #{glueLossSetting.createBy,jdbcType= VARCHAR} create_by, #{glueLossSetting.createTime,jdbcType=TIMESTAMP} create_time, #{glueLossSetting.updateBy,jdbcType= VARCHAR} update_by, #{glueLossSetting.updateTime,jdbcType=TIMESTAMP} update_time, #{glueLossSetting.delFlag,jdbcType= VARCHAR} del_flag, #{glueLossSetting.remark,jdbcType= VARCHAR} remark
) x

mapper.select:
WITH temp_table AS (
SELECT #{data.mixArea,jdbcType= VARCHAR} MIX_AREA, #{data.machineName,jdbcType= VARCHAR} MACHINE_NAME,#{rowNumber} row_numbers
) select m.MACHINE_CODE machineCode from T_MIX_MACHINE m right join temp_table t on m.MIX_AREA=t.MIX_AREA and m.MACHINE_NAME = t.MACHINE_NAME and m.del_flag ='0' order by t.row_numbers
